/**
 * Age-of-sail navy clothing, about 1800, generated by this project (MIT): seamen's slops, marines'
 * coatees and belts, officers' tailcoats with their facings, epaulettes and hats, for the Royal Navy
 * and the French Marine alike (the navies differ in colours, see packages/generator/src/navy-outfits.ts).
 *
 * - Cut from base-mesh helpers like the medieval kit (see medieval.ts): shirt, trousers, jacket,
 *   waistcoat, breeches, gaiters, coats, lapels, collar, cuffs, cross belts and the neck stock. They
 *   bend with the skin under every morph and animation.
 * - Built as new geometry like the golden age jewellery (see golden-age.ts): buttons, epaulettes and
 *   the neckerchief (bound to the torso), and the hats (bound to the skull).
 *
 * A coat's facings are their own garments (`navy-lapels`, `navy-collar`, `navy-cuffs`), so each takes
 * its colour: white lapels for a British officer, red cuffs for a French one, blue collar and cuffs for
 * a Royal Marine. In a crowd-level merged mesh every piece keeps its colour.
 */
import { PNG } from "pngjs";
import { IN, OUT, type Point, armPos, has, isArm, isLeg, legHole, legPos, legVolume, neckline } from "./garments";
import type { Vec3 } from "./geometry";
import type { LodSteps } from "./lod";
import {
  type GeneratedSpec,
  type GeneratedTexture,
  type Kit,
  Shape,
  Surface,
  add,
  addGenerated,
  cross,
  dot,
  headRing,
  linear,
  makeKit,
  norm,
  scale,
  sub,
  vertexNormals,
} from "./golden-age";
import { type Landmarks, type MedievalContext, type MedievalOutput, type MedievalSpec, bodice, buildSpecs, skirtTop, torsoBelow } from "./medieval";

const min = Math.min, max = Math.max;
const clamp01 = (t: number) => max(0, min(1, t));
const smooth = (t: number) => { const s = clamp01(t); return s * s * (3 - 2 * s); };
const mix = (a: number, b: number, t: number) => a + (b - a) * t;

export const NAVY_CLOTHING = "Age of sail clothing";
export const NAVY_ACCESSORIES = "Age of sail accessories";

/** Colours picked by eye (sRGB), shared with the presets' defaults. */
export const NAVY_COLORS = {
  navyBlue: "#1c2340",
  white: "#e9e4d6",
  duck: "#ddd6c3",
  black: "#18181b",
  gold: "#c9a24a",
  marineRed: "#a8232b",
  jacketBlue: "#26305a",
};

// ---------------------------------------------------------------------------------------------
// Cuts

/** Mean colour (sRGB, 0..1) of the striped print: the garment colour of a textured garment. */
export const STRIPES = { a: "#f0ebde", b: "#b3262c", pairs: 12 };
const STRIPES_MEAN = ((): [number, number, number] => {
  const hex = (h: string) => [16, 8, 0].map((s) => ((parseInt(h.slice(1), 16) >> s) & 255) / 255);
  const a = hex(STRIPES.a), b = hex(STRIPES.b);
  return [0, 1, 2].map((i) => (a[i] + b[i]) / 2) as [number, number, number];
})();

/** Vertical stripes (u across), half white, half red. */
export function stripesPng(): Buffer {
  const w = STRIPES.pairs * 16, h = 4;
  const png = new PNG({ width: w, height: h });
  const hex = (h: string) => [16, 8, 0].map((s) => (parseInt(h.slice(1), 16) >> s) & 255);
  const a = hex(STRIPES.a), b = hex(STRIPES.b);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const col = (x % 16) < 8 ? a : b;
      const o = (y * w + x) * 4;
      png.data[o] = col[0]; png.data[o + 1] = col[1]; png.data[o + 2] = col[2]; png.data[o + 3] = 255;
    }
  return PNG.sync.write(png);
}


/** Front of the torso (z ahead of the body's axis by `from`), 0..1. */
const front = (m: Landmarks, c: Point, from = 0.02, to = 0.08) => smooth((c.z - m.torso.center[1] - from) / (to - from));

/** Coat bodice hem: at the waist in front (cut away), at the seat at the back and sides. */
const coatHem = (m: Landmarks, c: Point, frontHem: number) => mix(m.pelvis - 0.02, frontHem, front(m, c));

/** Tails (cut from the skirt helper): behind a line slanting back from the hips, to `hemT`, with a vent at the back. */
const tails = (m: Landmarks, hemT: number, slant: number) => (c: Point) => {
  const cz = m.torso.center[1];
  const hem = min(c.y - m.hem(hemT), m.pelvis + 0.02 - c.y);
  const behind = min(cz + 0.03 - (m.pelvis - c.y) * slant - c.z, 0.17 - (m.pelvis - c.y) * 0.2 - Math.abs(c.x));
  const vent = c.z < cz ? -min(0.007 - Math.abs(c.x), m.hem(hemT * 0.45) - c.y) : IN;
  return min(hem, behind, vent);
};

/** Coat and jacket bodies sit this far out from the torso's outline (share of the push). */
/**
 * Distant levels for the pieces whose cut edges carry the uniform (the coat's open front, lapels,
 * cuffs, belts): the default crowd step (a fifth of the triangles, welded) closes the coat's front
 * and eats the lapels, so these keep more.
 */
const EDGE_LODS: LodSteps = [[1, 0.5, 0.01, 12000], [2, 0.4, 0.02, 2000]];
const COAT = { gap: 0.022, share: 0.5 };
const coatOffset = (m: Landmarks) => (c: Point) => m.torso.pushOut(c, COAT.gap, COAT.share);

/** Radial offset from the forearm's axis (sleeves fuller at the wrist, cuffs over them). */
const armOut = (m: Landmarks, amount: (t: number) => number) => (c: Point): Vec3 => {
  if (!isArm(c.bone) || has(c.bone, "clavicle")) return [0, 0, 0];
  const side = c.x >= 0 ? "l" : "r";
  const s = m.ctx.joint(`upperarm_${side}`), w = m.ctx.joint(`hand_${side}`);
  const [along, length] = armPos(c, m.ctx);
  const t = clamp01(along / length);
  const axis: Vec3 = [s[0] + (w[0] - s[0]) * t, s[1] + (w[1] - s[1]) * t, s[2] + (w[2] - s[2]) * t];
  const d: Vec3 = [c.x - axis[0], c.y - axis[1], c.z - axis[2]];
  const dir = norm(d);
  return scale(dir, amount(t));
};

/** Lapels: two panels on the chest from the waist to below the collar, meeting low and opening at the top. */
const lapelCut = (m: Landmarks) => (c: Point) => {
  if (isArm(c.bone) && !has(c.bone, "clavicle")) return OUT;
  if (isLeg(c.bone) || c.z < m.torso.center[1] + 0.02) return OUT;
  const y0 = m.waist - 0.01, y1 = m.neck - 0.035;
  const t = clamp01((c.y - y0) / (y1 - y0));
  const inner = 0.001 + 0.04 * smooth((t - 0.45) / 0.55);
  const width = 0.072 - 0.012 * t;
  const x = Math.abs(c.x);
  return min(x - inner, inner + width - x, c.y - y0, y1 - c.y);
};

/** Cuffs: the last `length` of the sleeve before `end` (0 = shoulder, 1 = wrist). */
const cuffCut = (m: Landmarks, length: number, end: number) => (c: Point) => {
  if (!has(c.bone, "lowerarm")) return OUT;
  const [s, l] = armPos(c, m.ctx);
  return min(s - (end - length) * l, end * l - s);
};

/** Distance of (x, y) from the segment a-b. */
const segment = (x: number, y: number, a: [number, number], b: [number, number]) => {
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const t = clamp01(((x - a[0]) * dx + (y - a[1]) * dy) / (dx * dx + dy * dy));
  return Math.hypot(x - a[0] - dx * t, y - a[1] - dy * t);
};

/** Wide trousers' stripes run down the leg: u goes round the leg (0 outside, 1 inside, mirrored), v down it. */
const legUV = (m: Landmarks) => (c: Point): [number, number] => {
  const s = c.x >= 0 ? 1 : -1;
  const hip = m.ctx.joint(s > 0 ? "thigh_l" : "thigh_r"), ankle = m.ctx.joint(s > 0 ? "foot_l" : "foot_r");
  const t = clamp01((hip[1] - c.y) / (hip[1] - ankle[1]));
  const ax = hip[0] + (ankle[0] - hip[0]) * t, az = hip[2] + (ankle[2] - hip[2]) * t;
  return [Math.abs(Math.atan2(c.z - az, (c.x - ax) * s)) / Math.PI, c.y];
};

/** Seaman's trousers: wide from the knee down, ending at the ankle. */
const slops = (m: Landmarks) => ({
  group: "helper-tights" as const,
  hideSkin: true,
  cut: (c: Point) => (isArm(c.bone) ? OUT : min(m.pelvis + 0.065 - c.y, legHole(c, m.ctx, 0.97))),
  offset: (c: Point): Vec3 => {
    if (has(c.bone, "thigh", "calf")) return legVolume((t) => 0.008 + 0.05 * smooth((t - 0.3) / 0.7))(c, m.ctx);
    return m.torso.pushOut(c, 0.008, 0.4);
  },
});

/** Officer's tailcoat (`tailT` hem of the tails, 0 hip .. 1 ankle) or a marine's coatee (short tails). */
const coat = (m: Landmarks, frontHem: number, tailT: number, slant: number) => [
  {
    group: "helper-tights" as const,
    cut: (c: Point, ctx: Landmarks["ctx"]) => bodice(m, 0.965, coatHem(m, c, frontHem), 0.082)(c, ctx),
    offset: (c: Point) => add(coatOffset(m)(c), armOut(m, (t) => 0.004 * t)(c)),
    smoothBind: 0.05,
    hideSkin: true,
  },
  { group: "helper-skirt" as const, cut: tails(m, tailT, slant), offset: (c: Point) => skirtTop(m, c, 0.024, 0.012) },
];

