// ---------------------------------------------------------------------------------------------
// Generated pieces

/** A loft through closed rings of equal length (quads between neighbours). */
export function loft(shape: Shape, rings: Vec3[][], bind: Kit["skull"], closed = true, inside?: Vec3) {
  const n = rings[0].length;
  const start = shape.binds.length;
  rings.forEach((ring, i) => ring.forEach((p, j) => shape.vertex(p, [j / n, i / max(1, rings.length - 1)], bind)));
  // Faces must look away from `inside` (a crowd mesh draws front faces only): flip if most of them don't.
  let facing = 0;
  if (inside)
    for (let i = 0; i + 1 < rings.length; i++)
      for (let j = 0; j + 1 < n; j++) {
        const a = rings[i][j], b = rings[i][j + 1], c = rings[i + 1][j];
        facing += Math.sign(dot(cross(sub(c, a), sub(b, a)), sub(a, inside)));
      }
  const flip = facing < 0;
  for (let i = 0; i + 1 < rings.length; i++)
    for (let j = 0; j < (closed ? n : n - 1); j++) {
      const a = start + i * n + j, b = start + i * n + ((j + 1) % n);
      const c = a + n, d = b + n;
      if (flip) shape.idx.push(a, b, c, b, d, c);
      else shape.idx.push(a, c, b, b, c, d);
    }
}

/** A flat cap of a closed ring: a fan to its centre (or `apex`). */
function cap(shape: Shape, ring: Vec3[], bind: Kit["skull"], apex?: Vec3) {
  const centre = apex ?? scale(ring.reduce((s, p) => add(s, p), [0, 0, 0] as Vec3), 1 / ring.length);
  const c = shape.vertex(centre, [0.5, 0.5], bind);
  const start = shape.binds.length;
  ring.forEach((p, j) => shape.vertex(p, [j / ring.length, 1], bind));
  for (let j = 0; j < ring.length; j++) shape.idx.push(c, start + j, start + ((j + 1) % ring.length));
}

/** Clearance of hats over the skin for the hair: at the brow, at the back, and over the crown. */
const HAT = { front: 0.03, back: 0.042, top: 0.035 };

/** The hat's own brow ring, eased into a smooth oval round the head (and clear of the hair). */
function hatRing(k: Kit, frontGap: number, backGap: number, lift = 0) {
  const { ring, out } = headRing(k, frontGap, backGap, lift);
  const c = scale(ring.reduce((s, p) => add(s, p), [0, 0, 0] as Vec3), 1 / ring.length);
  return { ring, out, c };
}

/** Low-crowned round hat with a narrow brim (seamen, marines). */
function roundHat(shape: Shape, k: Kit) {
  const { ring, out, c } = hatRing(k, HAT.front, HAT.back, 0.012);
  const top = max(k.headTop + HAT.top - 0.005, max(...ring.map((p) => p[1])) + 0.06);
  // Crown: straight sides, slightly narrower at the top, a flat top.
  const crown = [0, 0.33, 0.66, 1].map((t) => ring.map((p) => {
    const taper = 1 - 0.1 * t * t;
    return [c[0] + (p[0] - c[0]) * taper, mix(p[1], top, t), c[2] + (p[2] - c[2]) * taper] as Vec3;
  }));
  loft(shape, crown, k.skull, true, c);
  cap(shape, crown[crown.length - 1], k.skull);
  // Brim: 6 cm, turned up a little at the sides, 5 mm thick.
  const w = 0.07, th = 0.005;
  const rim = (dy: number, reach: number) => ring.map((p, i) => {
    const side = Math.abs(out[i][0]);
    return add(add(p, scale(out[i], reach)), [0, dy + reach * 0.08 * side * side, 0]) as Vec3;
  });
  loft(shape, [rim(0, 0), rim(0, w), rim(-th, w), rim(-th, 0), rim(0, 0)], k.skull);
}

/** Knitted cap pulled down over the head, the top flopping back (seamen; the French red bonnet). */
function knitCap(shape: Shape, k: Kit) {
  const { ring, c } = hatRing(k, 0.006, 0.01, -0.03);
  const apexY = k.headTop + 0.022;
  const rings: Vec3[][] = [];
  for (let i = 0; i <= 10; i++) {
    const t = i / 10;
    const a = (t * Math.PI) / 2;
    // A dome over the skull, its top drawn back and down like a stocking cap.
    const back = 0.05 * smooth((t - 0.55) / 0.45);
    rings.push(ring.map((p) => {
      const q: Vec3 = [c[0] + (p[0] - c[0]) * Math.cos(a), mix(p[1], apexY, Math.sin(a)) - 0.02 * back / 0.05 * t, c[2] + (p[2] - c[2]) * Math.cos(a) - back];
      return t < 0.95 ? k.head.pushOut(q, 0.012) : q;
    }));
  }
  loft(shape, rings, k.skull, true, c);
  cap(shape, rings[rings.length - 1], k.skull);
  // The rolled brim.
  const roll = ring.map((p) => add(p, scale(norm([p[0] - c[0], 0, p[2] - c[2]]), 0.006)) as Vec3);
  shape.tube([...roll, roll[0]], roll.map(() => 0.008).concat(0.008), roll.map(() => k.skull).concat(k.skull), 8, false);
}

/** The bicorne, worn athwartships: two half-moon flaps over the head meeting at the points. */
export function bicorneSurface(k: Kit) {
  const { ring, c } = hatRing(k, HAT.front, HAT.back, 0.01);
  const W = 0.21, H = max(0.17, k.headTop + HAT.top + 0.06 - c[1]);
  const half = max(...ring.map((p) => Math.abs(p[0] - c[0])));
  // Front and back of the brow ring at x (or the point where the flaps meet beyond the head).
  const edge = (x: number, sign: number) => {
    let best = ring[0], bd = Infinity;
    for (const p of ring) if ((p[2] - c[2]) * sign > 0 && Math.abs(p[0] - x) < bd) { bd = Math.abs(p[0] - x); best = p; }
    return best;
  };
  /** Point on a flap: x across (-W..W), t from the brim (0) to the crest (1), sign +1 front, -1 back. */
  const at = (x: number, t: number, sign: number): Vec3 => {
    const ax = Math.abs(x);
    const e = edge(c[0] + Math.sign(x) * min(ax, half * 0.98), sign);
    // Depth of the hat at x: the head's own depth inside, closing to the point beyond it.
    const depth = (e[2] - c[2]) * (ax <= half ? 1 : 1 - smooth((ax - half) / (W - half)));
    const base = ax <= half ? e[1] : mix(e[1], c[1] + 0.03, (ax - half) / (W - half));
    const crest = c[1] + H * Math.sqrt(max(0, 1 - (x / W) ** 2)) * 0.92 + 0.02;
    const y = mix(base, max(base, crest), t);
    const z = c[2] + depth * (1 - t * t * t) + sign * 0.01 * t;
    return [c[0] + x, y, z];
  };
  return { at, W, c };
}

function bicorne(shape: Shape, k: Kit) {
  const { at, W } = bicorneSurface(k);
  const sections: Vec3[][] = [];
  const N = 40, T = 6;
  for (let i = 0; i <= N; i++) {
    const x = -W + (2 * W * i) / N;
    const sec: Vec3[] = [];
    for (let j = 0; j <= T; j++) sec.push(at(x, j / T, 1));
    for (let j = T; j >= 0; j--) sec.push(at(x, j / T, -1));
    sections.push(sec);
  }
  loft(shape, sections, k.skull);
}

/** Gold lace along the bicorne's crest. */
function bicorneLace(shape: Shape, k: Kit) {
  const { at, W } = bicorneSurface(k);
  for (const sign of [1, -1]) {
    const path: Vec3[] = [];
    for (let i = 0; i <= 40; i++) path.push(add(at(-W + (2 * W * i) / 40, 0.97, sign), [0, 0, sign * 0.003]));
    shape.tube(path, path.map(() => 0.006), path.map(() => k.skull), 6);
  }
}

/** Cockade on the bicorne's front flap, to the wearer's left, with its loop. */
function cockade(shape: Shape, k: Kit) {
  const { at } = bicorneSurface(k);
  const x = 0.075, t = 0.5;
  const p = at(x, t, 1);
  const n = norm(cross(sub(at(x + 0.01, t, 1), at(x - 0.01, t, 1)), sub(at(x, t + 0.05, 1), at(x, t - 0.05, 1))));
  const nn = n[2] < 0 ? scale(n, -1) : n;
  const u = norm(cross([0, 1, 0], nn)), v = cross(nn, u);
  const r = 0.026, ringN = 24;
  const centre = add(p, scale(nn, 0.006));
  const front = shape.vertex(centre, [0.5, 0.5], k.skull);
  const start = shape.binds.length;
  for (let j = 0; j < ringN; j++) {
    const a = (j / ringN) * Math.PI * 2;
    shape.vertex(add(add(add(p, scale(nn, 0.004)), scale(u, Math.cos(a) * r)), scale(v, Math.sin(a) * r)), [0.5 + 0.5 * Math.cos(a), 0.5 + 0.5 * Math.sin(a)], k.skull);
  }
  for (let j = 0; j < ringN; j++) shape.idx.push(front, start + j, start + ((j + 1) % ringN));
}

const neckCache = new WeakMap<Kit, Surface>();
/** The neck's own skin (no shoulders), for collars that hug it. */
function neckSurface(k: Kit): Surface {
  const hit = neckCache.get(k);
  if (hit) return hit;
  const { mc } = k;
  const verts = k.bodyVerts.filter((v) => has(mc.dominantBone(v), "neck_01"));
  const s = new Surface(mc.positions, vertexNormals(mc.positions, mc.facesOf("body")), verts);
  neckCache.set(k, s);
  return s;
}

/** Standing collar: a band round the neck over the coat's neckline, open at the throat, `h` high. */
function standingCollar(shape: Shape, k: Kit, h: number) {
  const y0 = k.m.neck - 0.022, z = k.neck[2];
  const neck = neckSurface(k);
  const sections: Vec3[][] = [];
  const open = 0.42, n = 40, th = 0.006;
  for (let i = 0; i <= n; i++) {
    const a = open + ((Math.PI * 2 - 2 * open) * i) / n;
    const dir: Vec3 = [Math.sin(a), 0, Math.cos(a)];
    const at = (t: number, extra: number) => {
      // Clear of the neck by a gap that narrows towards the top edge; the front ends lower.
      const front = (1 + Math.cos(a)) / 2;
      const y = y0 + h * t * (1 - 0.35 * front);
      return add(neck.marchIn(add([0, y, z], scale(dir, 0.11)), scale(dir, -1), 0.026 - 0.01 * t), scale(dir, extra));
    };
    sections.push([at(0, 0), at(0.5, 0), at(1, 0), at(1, -th), at(0.5, -th), at(0, -th)]);
  }
  // Each section binds to the torso where its foot sits.
  const start = shape.binds.length;
  sections.forEach((sec, i) => sec.forEach((p, j) => shape.vertex(p, [i / n, j / (sec.length - 1)], k.bindTorso(sec[0]))));
  const m = sections[0].length;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < m - 1; j++) {
      const a = start + i * m + j, b = a + m;
      shape.idx.push(a, b, a + 1, a + 1, b, b + 1);
    }
}

/** Neckerchief: a roll round the base of the neck, a knot at the throat and two short ends. */
function neckerchief(shape: Shape, k: Kit) {
  const y = k.m.neck + 0.015, z = k.neck[2];
  const ring: Vec3[] = [];
  for (let i = 0; i < 48; i++) {
    const a = (i / 48) * Math.PI * 2;
    const dir: Vec3 = [Math.sin(a), 0, Math.cos(a)];
    // Lower at the front, where it is knotted.
    const yy = y - 0.025 * ((1 + Math.cos(a)) / 2) ** 2;
    ring.push(k.torso.marchIn(add([0, yy, z], scale(dir, 0.16)), scale(dir, -1), 0.013));
  }
  shape.tube([...ring, ring[0]], ring.map(() => 0.01).concat(0.01), ring.map((p) => k.bindTorso(p)).concat(k.bindTorso(ring[0])), 8);
  const knot = add(ring[0], [0, -0.004, 0.006]);
  shape.sphere(knot, [0.018, 0.015, 0.012], k.bindTorso(knot), 8, 6);
  for (const s of [1, -1]) {
    const end: Vec3[] = [];
    for (let i = 0; i <= 6; i++) {
      const t = i / 6;
      end.push(k.torso.marchIn([s * (0.008 + 0.022 * t), knot[1] - 0.01 - 0.1 * t, 0.5], [0, 0, -1], 0.016));
    }
    shape.tube(end, end.map((_, i) => 0.009 + 0.006 * (i / 6)), end.map((p) => k.bindTorso(p)), 8);
  }
}

/** Buttons: flattened domes at (x, y) on the front, sitting `lift` out from the torso's outline (coat thickness). */
function buttons(shape: Shape, k: Kit, at: [number, number][], lift: number, r = 0.0085) {
  for (const [x, y] of at) {
    const skin = k.torso.marchIn([x, y, 0.5], [0, 0, -1], 0);
    const p = add(add(skin, k.m.torso.pushOut({ x: skin[0], y: skin[1], z: skin[2] }, COAT.gap, COAT.share)), [0, 0, lift]);
    shape.sphere(p, [r, r, r * 0.45], k.bindTorso(p), 12, 6);
  }
}

/** Columns of buttons from `y0` to `y1` at the given x. */
const column = (xs: number[], y0: number, y1: number, count: number): [number, number][] =>
  xs.flatMap((x) => Array.from({ length: count }, (_, i) => [x, y0 + ((y1 - y0) * i) / (count - 1)] as [number, number]));

const shoulderCache = new WeakMap<Kit, { topAt: (x: number, z: number) => number }>();
/** The top of the shoulders (with the deltoids): the highest skin near (x, z), to lay epaulettes on. */
function shoulders(k: Kit) {
  const hit = shoulderCache.get(k);
  if (hit) return hit;
  const { mc } = k;
  const P = mc.positions;
  const verts = k.bodyVerts.filter((v) => has(mc.dominantBone(v), "clavicle", "upperarm", "spine_03"));
  const s = {
    topAt: (x: number, z: number) => {
      let y = -Infinity;
      for (const v of verts) if (Math.abs(P[v * 3] - x) < 0.015 && Math.abs(P[v * 3 + 2] - z) < 0.035) y = max(y, P[v * 3 + 1]);
      return y;
    },
  };
  shoulderCache.set(k, s);
  return s;
}

/** Gold epaulette on each `side` (+1 left, -1 right): a strap from the collar, a crescent and a bullion fringe. */
function epaulettes(shape: Shape, k: Kit, sides: number[]) {
  const surf = shoulders(k);
  const gap = 0.026;
  for (const s of sides) {
    const j = k.mc.joint(s > 0 ? "upperarm_l" : "upperarm_r");
    const onTop = (x: number, z: number): Vec3 => [x, surf.topAt(x, z) + gap, z];
    const x0 = s * 0.07, x1 = j[0] + s * 0.02;
    // The strap: a flat bar along the top of the shoulder.
    // Along the top of the shoulder from the crescent towards the collar, rising with the shoulder's slope.
    const end0 = onTop(x1, j[2]);
    const strap: Vec3[] = [];
    for (let i = 0; i <= 8; i++) {
      const x = mix(x0, x1, i / 8);
      strap.push([x, end0[1] + 0.22 * Math.abs(x1 - x), j[2]]);
    }
    const w = 0.045;
    for (const dy of [0, -0.004]) {
      const start = shape.binds.length;
      strap.forEach((p) => {
        for (const dz of [-w / 2, w / 2]) shape.vertex(add(p, [0, dy, dz]), [0, 0], k.bindTorso(p));
      });
      for (let i = 0; i < 8; i++) {
        const a = start + i * 2;
        shape.idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
    }
    // The crescent pad at the outer end, and the fringe hanging off its outer half.
    const end = strap[strap.length - 1];
    const bind = k.bindTorso(end);
    shape.sphere(add(end, [0, 0.002, 0]), [0.03, 0.009, 0.04], bind, 12, 6);
    const n = 15;
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + (Math.PI * i) / (n - 1);
      const root = add(end, [s * Math.cos(a) * 0.028, -0.002, Math.sin(a) * 0.038]);
      const dir = norm([s * Math.cos(a) * 0.35, -1, Math.sin(a) * 0.3]);
      const tip = add(root, scale(dir, 0.06));
      shape.tube([root, tip], [0.004, 0.0045], [bind, bind], 5);
    }
  }
}

/** French tricolour cockade: blue centre, white, red rim (u, v round the centre). */
export function tricolourPng(): Buffer {
  const s = 64;
  const png = new PNG({ width: s, height: s });
  for (let y = 0; y < s; y++)
    for (let x = 0; x < s; x++) {
      const r = Math.hypot(x + 0.5 - s / 2, y + 0.5 - s / 2) / (s / 2);
      const col = r < 0.38 ? [32, 52, 128] : r < 0.68 ? [238, 234, 226] : [178, 34, 40];
      const o = (y * s + x) * 4;
      png.data[o] = col[0]; png.data[o + 1] = col[1]; png.data[o + 2] = col[2]; png.data[o + 3] = 255;
    }
  return PNG.sync.write(png);
}

const TRICOLOUR: GeneratedTexture = { name: "navy-tricolour", png: () => tricolourPng() };

