/** Builds the navy wardrobe: helper cuts plus generated buttons, epaulettes, neckerchief and hats. */
export function buildNavy(mc: MedievalContext, out: string): MedievalOutput {
  const result = buildSpecs(mc, NAVY_CUT);
  addGenerated(result, makeKit(mc), NAVY_GENERATED, NAVY_ACCESSORIES, out);
  return result;
}

